"""Generate the uci commands that apply the Sensa van network layout.

Why uci and not the REST API: probed against a RUTX50 on RUTX_R_00.07.22.1,
the API returned 403 for 8 of the 13 config capabilities needed (vlan, dhcp,
firewall rules, firewall forwardings, routes, access_control,
attack_prevention, mdns) while returning 200 for 5 others on the same token
in the same session. The refused set is most of the job. RutOS is OpenWrt
underneath and uci reaches the whole config with no such split.

Output is a shell script. It can be pasted into an SSH session or piped to
`ssh root@<router> sh`, so it needs nothing installed on the router and
nothing installed on the laptop beyond an ssh client.

Standard library only, and no `homeassistant` import, for the same reason as
`teltonika_provision.py`: this has to run on a support laptop.
"""

from __future__ import annotations

from typing import Any

# uci names radios radio0 / radio1. On a RUTX50 radio0 is 2.4 GHz and radio1
# is 5 GHz (board.wlan carries wlan0 and wlan1, dual_band_ssid true). That
# mapping is a convention rather than a guarantee, so it is a parameter.
BAND_RADIO_DEFAULT = {"2g": "radio0", "5g": "radio1"}


class UciError(Exception):
    """The profile cannot be expressed as uci commands."""


def _netmask(subnet: str) -> str:
    """Only /24 is handled, which is all network_profile.json uses."""
    if not subnet.endswith("/24"):
        raise UciError(
            f"subnet {subnet!r} is not a /24; this generator only handles /24"
        )
    return "255.255.255.0"


def _quote(value: str) -> str:
    """Single-quote for sh, escaping any embedded quote.

    Wi-Fi passwords routinely contain characters the shell would otherwise
    eat, and an SSID can contain spaces.
    """
    return "'" + str(value).replace("'", "'\\''") + "'"


def _add_list(key: str, value: str) -> str:
    """One line that appends to a uci list without duplicating on re-run.

    `uci add_list` appends blindly, so a second run of the script would
    leave the zone with its network listed twice. Deleting first makes it
    a no-op when the value is already there; -q keeps a missing entry
    quiet and `|| true` keeps `set -e` from treating it as a failure.
    """
    q = _quote(value)
    return f"uci -q del_list {key}={q} || true; uci add_list {key}={q}"


def build_uci_script(
    profile: dict[str, Any],
    params: Any,
    band_radio: dict[str, str] | None = None,
    lan_device: str = "eth0",
    existing_lan_zone: str = "lan",
) -> list[str]:
    """Return the uci commands that apply the profile.

    Ordered so the run cannot cut itself off: the data network is never
    touched, and wireless comes last because renaming an SSID drops every
    wireless client, which may include the machine running this.

    Re-runnable. Every list append is preceded by a delete of the same
    value, and the data VLAN's port list is recomputed from what the
    router has rather than overwritten, so running the script twice
    leaves the router as it was after the first run.
    """
    radios = dict(BAND_RADIO_DEFAULT if band_radio is None else band_radio)
    template = profile.get("ssid_template", "{identity}_{suffix}")
    out: list[str] = []
    add = out.append

    segments = {s["key"]: s for s in profile.get("segments", [])}
    managed = [s for s in profile.get("segments", []) if s.get("managed")]
    managed_zones = {s["zone"] for s in managed}

    add("#!/bin/sh")
    add("# Sensa van network layout. Generated by provision_router.py.")
    add("# Review before running. The data network (VLAN 1, untagged) is")
    add("# deliberately never touched: the router is reached over it.")
    add("set -e")
    add("")

    # --- switch ---------------------------------------------------------
    # This board is swconfig (board.hwinfo.dsa is false). VLAN 1 (LAN) and
    # VLAN 2 (WAN) are fixed by the firmware (board.network_options
    # .readonly_vlans is 2), so a segment that owns a physical port gets
    # its own VLAN, tagged on the CPU port, and the port is taken out of
    # VLAN 1. eth0.<vlan> only exists once the switch_vlan entry does, so
    # this comes before the bridge that lists it.
    switch = profile.get("switch") or {}
    sw_dev = switch.get("device", "switch0")
    cpu = switch.get("cpu_port", 0)
    port_map = {str(k): int(v) for k, v in switch.get("lan_ports", {}).items()}
    reserved = {int(v) for v in switch.get("reserved_vlans", [1, 2])}
    wired = [s for s in managed if s.get("lan_ports")]
    if wired:
        add("# Wired ports. The data VLAN keeps whatever ports it has now,")
        add("# minus the ones handed to a segment below.")
        add("data_vlan=$(uci show network"
            " | sed -n \"s/^network\\.\\([^.]*\\)\\.vlan='1'$/\\1/p\""
            " | head -n1)")
        add("[ -n \"$data_vlan\" ] || { echo 'no switch_vlan section for"
            " VLAN 1' >&2; exit 1; }")
        add("")
    for seg in wired:
        key, vlan = seg["key"], seg["vlan_id"]
        if vlan in reserved:
            raise UciError(
                f"segment {key!r} has lan_ports but VLAN {vlan} is reserved "
                f"by the firmware; give it another vlan_id"
            )
        nums = []
        for label in seg["lan_ports"]:
            if str(label) not in port_map:
                raise UciError(
                    f"segment {key!r} names LAN {label}, which is not in "
                    f"switch.lan_ports ({sorted(port_map)})"
                )
            nums.append(port_map[str(label)])
        labels = ", ".join(f"LAN {lbl}" for lbl in seg["lan_ports"])
        plural = "s" if len(nums) > 1 else ""
        add(f"# {key}: {labels} (switch port{plural} "
            f"{' '.join(map(str, nums))}) -> VLAN {vlan}")
        # Reuse a section that already carries this VLAN id (the WebUI
        # creates anonymous ones); two switch_vlan sections with the same
        # id would fight. Only create the named section when none exists.
        add(f"sec=$(uci show network | sed -n "
            f"\"s/^network\\.\\([^.]*\\)\\.vlan='{vlan}'$/\\1/p\" | head -n1)")
        add(f"[ -n \"$sec\" ] || {{ uci set network.vlan_{key}=switch_vlan; "
            f"sec=vlan_{key}; }}")
        add(f"uci set \"network.$sec.device={sw_dev}\"")
        add(f"uci set \"network.$sec.vlan={vlan}\"")
        ports = " ".join([f"{cpu}t"] + [str(n) for n in nums])
        add(f"uci set \"network.$sec.ports={ports}\"")
        for n in nums:
            add("ports=$(uci get \"network.$data_vlan.ports\""
                f" | tr ' ' '\\n' | grep -vx '{n}'"
                " | tr '\\n' ' ' | sed 's/ $//')")
            add("uci set \"network.$data_vlan.ports=$ports\"")
        add("")

    # --- networks -------------------------------------------------------
    for seg in managed:
        key, vlan = seg["key"], seg["vlan_id"]
        add(f"# {key}: {seg['subnet']} on VLAN {vlan} ({seg['purpose']})")
        # A bridge, so wireless interfaces attach to the same network as the
        # tagged wired port.
        add(f"uci set network.{key}_dev=device")
        add(f"uci set network.{key}_dev.name={_quote('br-' + key)}")
        add(f"uci set network.{key}_dev.type='bridge'")
        if seg.get("lan_ports"):
            add(_add_list(f"network.{key}_dev.ports", f"{lan_device}.{vlan}"))
        add(f"uci set network.{key}=interface")
        add(f"uci set network.{key}.device={_quote('br-' + key)}")
        add(f"uci set network.{key}.proto='static'")
        add(f"uci set network.{key}.ipaddr={_quote(seg['router_ip'])}")
        add(f"uci set network.{key}.netmask={_quote(_netmask(seg['subnet']))}")
        # RutOS lists an interface on Network > LAN only when it is marked
        # as a LAN area. Without this the segment exists but is invisible
        # in the WebUI, which reads as "not configured" to anyone checking.
        add(f"uci set network.{key}.area_type='lan'")
        add("")

    # --- dhcp -----------------------------------------------------------
    add("# DHCP pools. Reservations for pinned kit go below .100 by hand.")
    for seg in managed:
        key = seg["key"]
        dhcp = seg.get("dhcp") or {}
        add(f"uci set dhcp.{key}=dhcp")
        add(f"uci set dhcp.{key}.interface={_quote(key)}")
        add(f"uci set dhcp.{key}.start={_quote(dhcp.get('start', 100))}")
        add(f"uci set dhcp.{key}.limit={_quote(dhcp.get('limit', 100))}")
        add(f"uci set dhcp.{key}.leasetime={_quote(dhcp.get('lease', '12h'))}")
    add("")

    # --- firewall zones -------------------------------------------------
    policy = profile.get("input_policy", {})
    forwarding = profile.get("forwarding", {})
    add("# input=REJECT is what keeps a segment off the router's own admin")
    add("# page. The forwarding rules below do NOT constrain traffic aimed")
    add("# at the router, so without this a zone that forwards nowhere can")
    add("# still open the WebUI on its own gateway.")
    for seg in managed:
        key, zone = seg["key"], seg["zone"]
        inp = str(policy.get(zone, "reject")).upper()
        wan_out = "wan" in forwarding.get(zone, [])
        add(f"# zone {zone}: input {inp}, "
            f"{'internet allowed' if wan_out else 'NO internet'}")
        add(f"uci set firewall.zone_{zone}=zone")
        add(f"uci set firewall.zone_{zone}.name={_quote(zone)}")
        add(_add_list(f"firewall.zone_{zone}.network", key))
        add(f"uci set firewall.zone_{zone}.input={_quote(inp)}")
        add(f"uci set firewall.zone_{zone}.output='ACCEPT'")
        add(f"uci set firewall.zone_{zone}.forward='REJECT'")
        add(f"uci set firewall.zone_{zone}.masq={_quote('1' if wan_out else '0')}")
        if wan_out:
            add(f"uci set firewall.fwd_{zone}_wan=forwarding")
            add(f"uci set firewall.fwd_{zone}_wan.src={_quote(zone)}")
            add(f"uci set firewall.fwd_{zone}_wan.dest='wan'")
        add("")

    # The data network reaches the other segments so HA can poll them.
    # Return traffic rides connection tracking, so there is no reverse rule
    # and none is wanted: that asymmetry IS the security model.
    # The profile calls the data segment's zone "data", but the zone that
    # already exists on the router is the stock OpenWrt "lan". Emitting
    # src='data' would point the rule at a zone that does not exist, and the
    # firewall would silently not forward. Translate on the way out.
    profile_data_zone = segments.get("data", {}).get("zone", "data")
    data_zone = existing_lan_zone
    add(f"# {data_zone} reaches the other segments so HA can poll them.")
    add("# No reverse rule: conntrack carries the replies, and a compromised")
    add("# device on those segments must not be able to start a connection.")
    for seg in managed:
        zone = seg["zone"]
        if zone not in forwarding.get(profile_data_zone, []):
            continue
        add(f"uci set firewall.fwd_lan_{zone}=forwarding")
        add(f"uci set firewall.fwd_lan_{zone}.src={_quote(data_zone)}")
        add(f"uci set firewall.fwd_lan_{zone}.dest={_quote(zone)}")
    add("")

    # --- input exceptions ----------------------------------------------
    add("# Without DHCP and DNS to the router itself, a rejected-input")
    add("# segment cannot get an address or resolve a name.")
    for exc in profile.get("input_exceptions", []):
        name = exc["name"]
        protos = exc["proto"]
        protos = [protos] if isinstance(protos, str) else list(protos)
        ports = exc["dest_ports"]
        port_value = str(ports[0]) if len(ports) == 1 else "-".join(
            str(p) for p in (min(ports), max(ports))
        )
        for zone in exc["zones"]:
            if zone not in managed_zones:
                continue
            rule = f"rule_{zone}_{name}"
            add(f"uci set firewall.{rule}=rule")
            add(f"uci set firewall.{rule}.name={_quote(f'Allow-{name.upper()}-{zone}')}")
            add(f"uci set firewall.{rule}.src={_quote(zone)}")
            add(f"uci set firewall.{rule}.dest_port={_quote(port_value)}")
            add(f"uci set firewall.{rule}.target='ACCEPT'")
            for proto in protos:
                add(_add_list(f"firewall.{rule}.proto", proto))
    add("")

    # --- zone exceptions -----------------------------------------------
    # One port between zones that otherwise reject each other (Sensa devices
    # on iot fetching firmware from the box on 8099). The profile's "data"
    # zone is the router's existing lan zone, translated as above.
    exceptions = profile.get("zone_exceptions", [])
    if exceptions:
        add("# Single ports between zones that otherwise reject each other.")
    for exc in exceptions:
        src = exc["from"]
        dest = data_zone if exc["to"] == profile_data_zone else exc["to"]
        if src not in managed_zones:
            continue
        protos = exc["proto"]
        protos = [protos] if isinstance(protos, str) else list(protos)
        ports = exc["dest_ports"]
        port_value = str(ports[0]) if len(ports) == 1 else " ".join(str(p) for p in ports)
        name = exc["name"]
        rule = f"rule_{src}_{name}"
        label = f"Allow-{name.upper()}-{src}-{dest}"
        add(f"uci set firewall.{rule}=rule")
        add(f"uci set firewall.{rule}.name={_quote(label)}")
        add(f"uci set firewall.{rule}.src={_quote(src)}")
        add(f"uci set firewall.{rule}.dest={_quote(dest)}")
        add(f"uci set firewall.{rule}.dest_port={_quote(port_value)}")
        add(f"uci set firewall.{rule}.target='ACCEPT'")
        for proto in protos:
            add(_add_list(f"firewall.{rule}.proto", proto))
    if exceptions:
        add("")

    add("uci commit network")
    add("uci commit dhcp")
    add("uci commit firewall")
    add("")

    # --- wireless, last -------------------------------------------------
    add("# Wireless LAST: renaming an SSID drops every wireless client,")
    add("# which may include the machine running this script.")
    for ssid in profile.get("ssids", []):
        seg_key = ssid["segment"]
        name = params.ssid_for(ssid["suffix"], template)
        password = getattr(params, ssid["password_param"], "")
        network = "lan" if seg_key == "data" else seg_key
        for band in ssid.get("bands", []):
            radio = radios.get(band)
            if not radio:
                continue
            sec = f"wifi_{ssid['suffix']}_{band}"
            add(f"# {name} on {radio} ({band}), network {network}")
            add(f"uci set wireless.{sec}=wifi-iface")
            add(f"uci set wireless.{sec}.device={_quote(radio)}")
            add(f"uci set wireless.{sec}.mode='ap'")
            add(f"uci set wireless.{sec}.network={_quote(network)}")
            add(f"uci set wireless.{sec}.ssid={_quote(name)}")
            add(f"uci set wireless.{sec}.encryption='psk2'")
            add(f"uci set wireless.{sec}.key={_quote(password)}")
            if ssid.get("client_isolation"):
                # A radio setting, not a firewall rule: two clients on one
                # SSID otherwise talk through the access point without the
                # traffic ever being routed, so no zone policy sees it.
                add(f"uci set wireless.{sec}.isolate='1'")
            add(f"uci set wireless.{radio}.disabled='0'")
            add("")

    add("uci commit wireless")
    add("")
    add("# Apply.")
    add("/etc/init.d/network reload")
    add("/etc/init.d/dnsmasq restart")
    add("/etc/init.d/firewall restart")
    add("wifi reload")
    add("")
    add("echo 'Done. Verify from a guest client that the router admin page'")
    add("echo 'is unreachable on 443, and that the internet still works.'")
    return out
